class LRU {
  #max; #map = new Map();
  constructor(max = 100) { this.#max = max; }
  get(key) {
    if (!this.#map.has(key)) return undefined;
    const entry = this.#map.get(key);
    if (entry.expires < Date.now()) { this.#map.delete(key); return undefined; }
    this.#map.delete(key); this.#map.set(key, entry);        // mark as recently used
    return entry.value;
  }
  set(key, value, ttlMs = 60_000) {
    this.#map.delete(key);
    this.#map.set(key, { value, expires: Date.now() + ttlMs });
    if (this.#map.size > this.#max) this.#map.delete(this.#map.keys().next().value);  // evict oldest
  }
}

const cache = new LRU(500);
export async function getProduct(id) {
  const key = `product:${id}`;
  const hit = cache.get(key);
  if (hit) return hit;
  const product = await db.products.findById(id);
  cache.set(key, product, 30_000);
  return product;
}

