import { pipeline } from 'node:stream/promises';
import { Transform } from 'node:stream';

app.get('/export/orders.csv', async (req, res, next) => {
  try {
    res.set({ 'Content-Type': 'text/csv; charset=utf-8', 'Content-Disposition': 'attachment; filename="orders.csv"' });

    const cursor = Order.find().lean().cursor();          // Mongoose cursor (Readable, objectMode)
    const toCsv = new Transform({
      writableObjectMode: true,
      construct(cb) { this.push('id,customer,total\n'); cb(); },
      transform(o, _enc, cb) { cb(null, `${o._id},${JSON.stringify(o.customer)},${o.total}\n`); },
    });

    await pipeline(cursor, toCsv, res);
  } catch (err) {
    if (!res.headersSent) next(err); else res.destroy(err);
  }
});

import { stat } from 'node:fs/promises';
import { createReadStream } from 'node:fs';
import { pipeline } from 'node:stream/promises';

export async function sendVideo(req, res, file) {
  const { size } = await stat(file);
  const range = req.headers.range;               // "bytes=1000-"

  if (!range) {
    res.writeHead(200, { 'Content-Length': size, 'Content-Type': 'video/mp4', 'Accept-Ranges': 'bytes' });
    return pipeline(createReadStream(file), res);
  }
  const [s, e] = range.replace('bytes=', '').split('-');
  const start = Number(s);
  const end = e ? Number(e) : size - 1;
  res.writeHead(206, {
    'Content-Range': `bytes ${start}-${end}/${size}`,
    'Accept-Ranges': 'bytes',
    'Content-Length': end - start + 1,
    'Content-Type': 'video/mp4',
  });
  await pipeline(createReadStream(file, { start, end }), res);
}

