// every instance runs this, but only the lock holder does the work
async function runNightlyJob() {
  const got = await redis.set('lock:nightly-report', process.pid, { NX: true, EX: 300 });
  if (!got) return;                      // another instance has it
  try {
    await buildReport();
  } finally {
    await redis.del('lock:nightly-report');
  }
}

// queue.js
import { Queue, Worker } from 'bullmq';
const connection = { host: '127.0.0.1', port: 6379 };

export const emailQueue = new Queue('email', { connection });

// in the API
app.post('/signup', async (req, res) => {
  const user = await createUser(req.body);
  await emailQueue.add('welcome', { userId: user.id }, {
    attempts: 5,
    backoff: { type: 'exponential', delay: 2000 },
    removeOnComplete: 1000,
    jobId: `welcome-${user.id}`,           // dedupe
  });
  res.status(202).json({ id: user.id });
});

// worker.js - separate process
const worker = new Worker('email', async (job) => {
  const user = await findUser(job.data.userId);
  await sendEmail(user.email, 'Welcome!');
  return { sent: true };
}, { connection, concurrency: 10 });

worker.on('failed', (job, err) => console.error(`job ${job?.id} failed`, err.message));
process.on('SIGTERM', async () => { await worker.close(); process.exit(0); });

